/* global Office, document, window, fetch */

// Flujo anterior (v4): solo para usuarios que aún tienen el manifest viejo (sin clave).
// Eliminar cuando todos tengan el manifest nuevo y la v4 esté apagada.
const FLOW_URL_V4 =
  "https://default3602aff1a179420eb9e6867ac2486b.86.environment.api.powerplatform.com:443/powerautomate/automations/direct/workflows/47e4bbe0e3ae44188b71d05113d12505/triggers/manual/paths/invoke?api-version=1&sp=%2Ftriggers%2Fmanual%2Frun&sv=1.0&sig=wOV3rtYjdhN2jI3Hr2e9fe5XhzfuuaNjW_R1u9giGO0";

// Flujo nuevo (v5): valida la clave que viene en el manifest (?k=...).
const FLOW_URL_V5 = "https://default3602aff1a179420eb9e6867ac2486b.86.environment.api.powerplatform.com:443/powerautomate/automations/direct/cu/19/workflows/2dd3a32deb554864a284db31a79b02b8/triggers/manual/paths/invoke?api-version=1&sp=%2Ftriggers%2Fmanual%2Frun&sv=1.0&sig=9l1GVjnQjcfPY6iPp1BHPXZpdnwHv49PxtfEf9_2dq4";

// Dominios internos: no reciben encuesta. El flow aplica el mismo filtro.
const INTERNAL_DOMAINS = ["@tlaservices.com"];

// Marca guardada en el propio correo (custom properties del add-in) para recordar que ya se pidió la encuesta.
const SENT_PROP = "csatSurveySent";

const state = {
  item: null,
  external: [], // { name, email, field: "to" | "cc", selected }
  internal: [],
  customProps: null,
};

// La clave NO está en este código (que es público): la pone el manifest instalado en el tenant.
function getKey() {
  try {
    return new URLSearchParams(window.location.search).get("k") || "";
  } catch (e) {
    return "";
  }
}

function $(id) {
  return document.getElementById(id);
}

function isInternal(email) {
  const e = email.toLowerCase();
  return INTERNAL_DOMAINS.some((d) => e.endsWith(d));
}

// Une To y Cc sin repetir (ignorando mayúsculas) y separa externos de internos.
function collectRecipients(item) {
  const seen = {};
  const external = [];
  const internal = [];
  [["to", item.to], ["cc", item.cc]].forEach(([field, list]) => {
    (list || []).forEach((r) => {
      const email = (r.emailAddress || "").trim();
      if (!email) return;
      const key = email.toLowerCase();
      if (seen[key]) return;
      seen[key] = true;
      const rec = { name: r.displayName || email, email, field, selected: true };
      (isInternal(email) ? internal : external).push(rec);
    });
  });
  return { external, internal };
}

function recipientLabel(rec) {
  return rec.name && rec.name.toLowerCase() !== rec.email.toLowerCase() ? `${rec.name} <${rec.email}>` : rec.email;
}

function renderRecipient(rec, selectable) {
  const li = document.createElement("li");
  const label = document.createElement("label");
  label.className = "recipient";

  if (selectable) {
    const cb = document.createElement("input");
    cb.type = "checkbox";
    cb.checked = rec.selected;
    cb.addEventListener("change", () => {
      rec.selected = cb.checked;
      updateButton();
    });
    label.appendChild(cb);
  }

  const text = document.createElement("span");
  text.className = "recipient__text";
  const name = document.createElement("span");
  name.className = "recipient__name";
  name.textContent = rec.name;
  text.appendChild(name);
  if (rec.name !== rec.email) {
    const email = document.createElement("span");
    email.className = "recipient__email";
    email.textContent = rec.email;
    text.appendChild(email);
  }
  label.appendChild(text);
  li.appendChild(label);
  return li;
}

function renderLists() {
  const ext = $("external-list");
  const int = $("internal-list");
  ext.textContent = "";
  int.textContent = "";
  state.external.forEach((r) => ext.appendChild(renderRecipient(r, true)));
  state.internal.forEach((r) => int.appendChild(renderRecipient(r, false)));
  $("recipients-section").hidden = state.external.length === 0;
  $("internal-section").hidden = state.internal.length === 0;
}

// kind: ok | warn | err | info. items: lista opcional de textos.
function showStatus(kind, title, body, items) {
  const box = $("status");
  box.className = `status status--${kind}`;
  box.textContent = "";

  const t = document.createElement("p");
  t.className = "status__title";
  t.textContent = title;
  box.appendChild(t);

  if (body) {
    const b = document.createElement("p");
    b.className = "status__body";
    b.textContent = body;
    box.appendChild(b);
  }
  if (items && items.length) {
    const ul = document.createElement("ul");
    ul.className = "status__list";
    items.forEach((txt) => {
      const li = document.createElement("li");
      li.textContent = txt;
      ul.appendChild(li);
    });
    box.appendChild(ul);
  }
  box.hidden = false;
}

function hideStatus() {
  $("status").hidden = true;
}

function selectedRecipients() {
  return state.external.filter((r) => r.selected);
}

function updateButton() {
  const btn = $("run");
  const n = selectedRecipients().length;
  btn.disabled = n === 0;
  $("run-label").textContent = n > 1 ? `Send survey to ${n} recipients` : "Send survey";
}

function setBusy(busy) {
  const btn = $("run");
  btn.classList.toggle("btn--busy", busy);
  btn.disabled = busy;
  btn.setAttribute("aria-busy", busy ? "true" : "false");
  $("run-label").textContent = busy ? "Sending…" : "Send survey";
  document.querySelectorAll(".recipient input").forEach((cb) => {
    cb.disabled = busy;
  });
}

function formatDate(iso) {
  try {
    return new Date(iso).toLocaleString();
  } catch (e) {
    return iso;
  }
}

// Lee la marca "ya enviada" del correo. Si falla (cliente sin soporte), sigue sin ella.
function loadCustomProps(item) {
  return new Promise((resolve) => {
    try {
      item.loadCustomPropertiesAsync((res) => {
        resolve(res.status === Office.AsyncResultStatus.Succeeded ? res.value : null);
      });
    } catch (e) {
      resolve(null);
    }
  });
}

function saveSentMark(recipients) {
  const props = state.customProps;
  if (!props) return;
  try {
    props.set(SENT_PROP, JSON.stringify({ at: new Date().toISOString(), to: recipients.map((r) => r.email) }));
    props.saveAsync(() => {});
  } catch (e) {
    // No es crítico: el flow igual bloquea duplicados por MessageId.
  }
}

function readSentMark() {
  try {
    const raw = state.customProps && state.customProps.get(SENT_PROP);
    return raw ? JSON.parse(raw) : null;
  } catch (e) {
    return null;
  }
}

function showSuccess(recipients) {
  $("recipients-section").hidden = true;
  $("internal-section").hidden = true;
  $("run").hidden = true;
  $("hint").hidden = true;
  showStatus(
    "ok",
    "✓ Survey sent",
    recipients.length === 1 ? "The survey was sent to:" : `The survey was sent to ${recipients.length} recipients:`,
    recipients.map(recipientLabel)
  );
}

export async function run() {
  const recipients = selectedRecipients();
  if (!recipients.length) return;

  hideStatus();
  setBusy(true);

  try {
    const item = state.item;
    const key = getKey();

    const data = {
      metadata: {
        sourceMessageId: item.internetMessageId || "",
        subject: item.subject || "",
        user: Office.context.mailbox.userProfile.emailAddress,
      },
      recipients: {
        to: recipients.filter((r) => r.field === "to").map((r) => r.email),
        cc: recipients.filter((r) => r.field === "cc").map((r) => r.email),
      },
    };
    if (key) data.auth = { key: key };

    const response = await fetch(key ? FLOW_URL_V5 : FLOW_URL_V4, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(data),
    });

    // El flow responde 202 apenas recibe el pedido. Los fallos dentro del flow no llegan acá:
    // Power Automate avisa por email al dueño. Acá solo cae lo que nunca llegó al flow
    // (sin conexión, flow apagado, URL inválida): ahí sí conviene que el usuario reintente.
    if (!response.ok) {
      throw new Error(`The survey service answered ${response.status}.`);
    }

    saveSentMark(recipients);
    setBusy(false);
    showSuccess(recipients);
  } catch (error) {
    console.error("CSAT error:", error);
    setBusy(false);
    updateButton();
    $("run-label").textContent = "Try again";
    showStatus(
      "err",
      "The survey could not be sent",
      "We could not reach the survey service, so nothing was sent. Check your connection and try again." +
        (error && error.message ? ` (${error.message})` : "")
    );
  }
}

async function init() {
  const item = Office.context.mailbox.item;
  state.item = item;

  $("sideload-msg").hidden = true;
  $("app-body").hidden = false;
  $("subject").textContent = item.subject || "(no subject)";
  $("subject").title = item.subject || "";

  const lists = collectRecipients(item);
  state.external = lists.external;
  state.internal = lists.internal;
  renderLists();
  updateButton();
  $("run").onclick = run;

  state.customProps = await loadCustomProps(item);
  const mark = readSentMark();
  if (mark) {
    $("recipients-section").hidden = true;
    $("internal-section").hidden = true;
    $("run").hidden = true;
    $("hint").hidden = true;
    showStatus("info", "Survey already sent", `Sent on ${formatDate(mark.at)} to:`, mark.to || []);
    return;
  }

  if (!state.external.length) {
    $("run").disabled = true;
    showStatus(
      "warn",
      "No client recipients",
      "This email has no external addresses in To or Cc, so there is nobody to send the survey to."
    );
  }
}

Office.onReady((info) => {
  if (info.host === Office.HostType.Outlook) {
    init();
  }
});
